/* Las dos tablas de INVT-01. Solo tokens de `tokens.css`. */

.sectionTitle {
  font-family: var(--bw-font-title);
  font-weight: 600;
  font-size: var(--bw-size-label);
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-divider);
  color: var(--bw-steel-mist);
  margin: 28px 0 10px;
}

.wrap {
  overflow-x: auto;
  border: 1px solid var(--bw-line-steel);
  border-radius: 5px;
  margin-bottom: 8px;
}

.table {
  width: 100%;
  border-collapse: collapse;
  font-size: var(--bw-size-input);
}

.th {
  background: var(--bw-surface-mist);
  padding: 9px 14px;
  text-align: left;
  font-family: var(--bw-font-title);
  font-weight: 600;
  font-size: var(--bw-size-label);
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-divider);
  color: var(--bw-steel-mist);
  border-bottom: 1px solid var(--bw-line-steel);
  white-space: nowrap;
}

.td {
  padding: 11px 14px;
  border-bottom: 1px solid var(--bw-divider-mist);
  color: var(--bw-ink-steel);
  vertical-align: middle;
}

.table tr:last-child .td {
  border-bottom: none;
}

.table tbody tr:hover .td {
  background: var(--bw-row-hover-tint);
}

/* Van después de `.td`: el selector de celda no pisa estas reglas porque el
   elemento lleva las dos clases y la última en el atributo decide en igualdad. */
.mono {
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-label);
  color: var(--bw-steel-mist);
}

.pendingDays {
  color: var(--bw-brass);
}

.name {
  font-weight: 500;
  color: var(--bw-deep-steel);
}

.badge {
  display: inline-block;
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-divider);
  padding: 2px 7px;
  border-radius: 2px;
  white-space: nowrap;
}

.badgePending {
  background: var(--bw-chip-active-bg);
  color: var(--bw-primary-dark);
  border: 1px solid var(--bw-chip-active-border);
}

.badgeAccepted {
  background: var(--bw-badge-success-bg);
  color: var(--bw-success-dark);
  border: 1px solid var(--bw-badge-success-border);
}

.badgeExpired {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-ink-steel-soft);
  border: 1px solid var(--bw-badge-neutral-border);
}

.badgeAdmin {
  background: var(--bw-tag-bg);
  color: var(--bw-brass);
  border: 1px solid var(--bw-tag-border);
}

.badgeEditor {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-ink-steel-soft);
  border: 1px solid var(--bw-badge-neutral-border);
}

.badgeActive {
  background: var(--bw-badge-success-bg);
  color: var(--bw-success-dark);
  border: 1px solid var(--bw-badge-success-border);
}

.badgeSuspended {
  background: var(--bw-sensitive-bg);
  color: var(--bw-sensitive-text);
  border: 1px solid var(--bw-badge-danger-border);
}

.badgeNeutral {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-ink-steel-soft);
  border: 1px solid var(--bw-badge-neutral-border-soft);
}

.emptyCell {
  padding: 18px 14px;
  color: var(--bw-steel-mist);
  text-align: center;
}

.actionButton {
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-label);
  padding: 4px 10px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  background: var(--bw-warm-cream);
  color: var(--bw-ink-steel);
  cursor: pointer;
  transition: border-color 0.15s, color 0.15s;
}

.actionButton:hover:not(:disabled) {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.actionButton:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* Va después de `.actionButton`: el botón destructivo pisa borde y color. */
.actionDanger {
  border-color: var(--bw-badge-danger-border);
  color: var(--bw-error-text);
  background: var(--bw-sensitive-bg);
}

.actionDanger:hover:not(:disabled) {
  border-color: var(--bw-danger);
  background: var(--bw-danger-hover-bg);
}

.none {
  font-size: var(--bw-size-label);
  color: var(--bw-line-steel-strong);
}

import {
  CANNOT_REMOVE_OWN_ADMIN,
  canRemove,
  expiresInLabel,
  memberStateLabel,
  roleLabel,
  sentAtLabel,
  type InvitationRow,
  type InvitationStatus,
  type TeamMember,
} from '../../lib/invitations';
import styles from './InvitationTables.module.css';

interface Props {
  invitations: InvitationRow[];
  team: TeamMember[];
  selfId: string;
  busy: boolean;
  onResend: (invitationId: string) => void;
  onRemove: (member: TeamMember) => void;
}

const CANNOT_REMOVE_EDITOR = 'Solo se pueden eliminar usuarios con rol Editor';

function statusClass(status: InvitationStatus): string {
  if (status === 'Aceptada') return styles.badgeAccepted;
  if (status === 'Expirada') return styles.badgeExpired;
  return styles.badgePending;
}

function stateClass(state: string): string {
  if (state === 'ACTIVE') return styles.badgeActive;
  if (state === 'SUSPENDED') return styles.badgeSuspended;
  return styles.badgeNeutral;
}

/**
 * Las dos tablas de INVT-01. Presentacional: no llama a la red y no guarda estado.
 *
 * `onRemove` recibe el MIEMBRO ENTERO, no su id: el diálogo de confirmación pinta
 * su nombre y su email, y la pantalla es la que decide qué hacer con él.
 */
export function InvitationTables({ invitations, team, selfId, busy, onResend, onRemove }: Props) {
  return (
    <>
      <h2 className={styles.sectionTitle}>Invitaciones enviadas</h2>
      <div className={styles.wrap}>
        <table className={styles.table} aria-label="Invitaciones enviadas">
          <thead>
            <tr>
              <th scope="col" className={styles.th}>
                Email
              </th>
              <th scope="col" className={styles.th}>
                Estado
              </th>
              <th scope="col" className={styles.th}>
                Fecha de envío
              </th>
              <th scope="col" className={styles.th}>
                Expira en
              </th>
              <th scope="col" className={styles.th}>
                Acciones
              </th>
            </tr>
          </thead>
          <tbody>
            {invitations.length === 0 ? (
              <tr>
                <td className={styles.emptyCell} colSpan={5}>
                  Todavía no has enviado ninguna invitación.
                </td>
              </tr>
            ) : (
              invitations.map((invitation) => (
                <tr key={invitation.id}>
                  <td className={`${styles.td} ${styles.mono}`}>{invitation.email}</td>
                  <td className={styles.td}>
                    <span className={`${styles.badge} ${statusClass(invitation.status)}`}>
                      {invitation.status}
                    </span>
                  </td>
                  <td className={`${styles.td} ${styles.mono}`}>{sentAtLabel(invitation.sentAt)}</td>
                  <td
                    className={
                      invitation.status === 'Pendiente'
                        ? `${styles.td} ${styles.mono} ${styles.pendingDays}`
                        : `${styles.td} ${styles.mono}`
                    }
                  >
                    {expiresInLabel(invitation.daysLeft)}
                  </td>
                  <td className={styles.td}>
                    {invitation.status === 'Expirada' ? (
                      <button
                        type="button"
                        className={styles.actionButton}
                        aria-label={`Reenviar ${invitation.email}`}
                        disabled={busy}
                        onClick={() => onResend(invitation.id)}
                      >
                        Reenviar
                      </button>
                    ) : (
                      <span className={styles.none}>—</span>
                    )}
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      <h2 className={styles.sectionTitle}>Usuarios activos</h2>
      <div className={styles.wrap}>
        <table className={styles.table} aria-label="Usuarios activos">
          <thead>
            <tr>
              <th scope="col" className={styles.th}>
                Nombre
              </th>
              <th scope="col" className={styles.th}>
                Email
              </th>
              <th scope="col" className={styles.th}>
                Rol
              </th>
              <th scope="col" className={styles.th}>
                Estado
              </th>
              <th scope="col" className={styles.th}>
                Acciones
              </th>
            </tr>
          </thead>
          <tbody>
            {team.map((member) => (
              <tr key={member.id}>
                <td className={`${styles.td} ${styles.name}`}>{member.fullName}</td>
                <td className={`${styles.td} ${styles.mono}`}>{member.email}</td>
                <td className={styles.td}>
                  <span
                    className={`${styles.badge} ${
                      member.role === 'ADMIN' ? styles.badgeAdmin : styles.badgeEditor
                    }`}
                  >
                    {roleLabel(member.role)}
                  </span>
                </td>
                <td className={styles.td}>
                  <span className={`${styles.badge} ${stateClass(member.state)}`}>
                    {memberStateLabel(member.state)}
                  </span>
                </td>
                <td className={styles.td}>
                  {canRemove(member, selfId) ? (
                    <button
                      type="button"
                      className={`${styles.actionButton} ${styles.actionDanger}`}
                      aria-label={`Eliminar ${member.fullName}`}
                      disabled={busy}
                      onClick={() => onRemove(member)}
                    >
                      Eliminar
                    </button>
                  ) : (
                    <span
                      className={styles.none}
                      title={
                        member.id === selfId ? CANNOT_REMOVE_OWN_ADMIN : CANNOT_REMOVE_EDITOR
                      }
                    >
                      —
                    </span>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </>
  );
}

