import { useEffect, useRef, useState, type ChangeEvent } from 'react';
import {
  LIMIT_NOTICE,
  capacityDetail,
  capacityDots,
  capacityLabel,
  emailHasAccount,
  fetchInvitations,
  fetchTeam,
  inviteMember,
  isValidEmail,
  limitReached,
  removeMember,
  resendInvitation,
  type CapacityDot,
  type InvitationRow,
  type TeamMember,
} from '../../lib/invitations';
import { errorMessage, type MemberProfile } from '../../lib/session';
import { InvitationTables } from './InvitationTables';
import { RemoveMemberDialog } from './RemoveMemberDialog';
import styles from './Invitations.module.css';

interface Props {
  profile: MemberProfile;
}

/** El título de cada punto del indicador de capacidad (HTML aprobado). */
const DOT_TITLES: Record<CapacityDot, string> = {
  used: 'Usuario activo',
  inv: 'Invitación pendiente',
  free: 'Plaza libre',
};

/** Las clases de los puntos de capacidad, una por tipo. */
const DOT_CLASSES: Record<CapacityDot, string> = {
  used: styles.dotUsed,
  inv: styles.dotInv,
  free: styles.dotFree,
};

/**
 * El correo de invitación NO se envía: no hay proveedor de correo en el proyecto
 * ni flujo de registro por invitación. La invitación queda REGISTRADA (F-212), y
 * el texto aprobado del mock («el usuario recibirá un email…») afirmaría un envío
 * que no ocurre.
 */
const INVITE_OK =
  'Invitación registrada. El envío del correo de invitación llega con el flujo de registro por invitación.';

const RESEND_OK = 'Invitación reenviada.';
const EMAIL_TAKEN = 'Este email ya tiene cuenta en Bearingworld.io.';

function message(err: unknown): string {
  return errorMessage(err instanceof Error ? err : new Error(String(err)));
}

/**
 * INVT-01 · Panel de Gestión de Invitaciones.
 *
 * Es la PANTALLA: posee todo el estado y es el único sitio que llama a la red.
 * `InvitationTables` y `RemoveMemberDialog` son presentacionales.
 *
 * El servidor manda: el límite de 5, «email ya registrado» y quién puede qué los
 * hacen cumplir las funciones de `0037`. Aquí solo se guarda lo que devuelven y se
 * pinta lo que `lib/invitations` calcula (plazas, etiquetas, puntos).
 *
 * Tres decisiones de estado que se ven en los tests:
 *
 * - La **comprobación de email** guarda el resultado JUNTO AL TEXTO al que
 *   corresponde: si llega la respuesta de un texto que ya no está en el campo, no
 *   se pinta y no bloquea nada. Un rechazo es «no se sabe»: no bloquea el envío,
 *   el servidor lo comprobará.
 * - La **recarga** tras invitar, reenviar o eliminar no vuelve a poner la pantalla
 *   en estado de carga: los mensajes que acaban de aparecer se quedarían sin
 *   pintar. Solo la primera carga muestra «Cargando invitaciones…».
 * - El **diálogo** vive aquí: la pantalla guarda el miembro pendiente y el error
 *   del servidor. Si `removeMember` rechaza, el diálogo SIGUE abierto.
 */
export function Invitations({ profile }: Props) {
  const isAdmin = profile.role === 'ADMIN';

  const [team, setTeam] = useState<TeamMember[]>([]);
  const [invitations, setInvitations] = useState<InvitationRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [reloadToken, setReloadToken] = useState(0);

  const [email, setEmail] = useState('');
  const [check, setCheck] = useState<{ email: string; hasAccount: boolean } | null>(null);
  const [checking, setChecking] = useState(false);
  const [sending, setSending] = useState(false);
  const [resending, setResending] = useState(false);
  const [feedback, setFeedback] = useState<{ tone: 'ok' | 'error'; text: string } | null>(null);

  const [pendingRemove, setPendingRemove] = useState<TeamMember | null>(null);
  const [removeError, setRemoveError] = useState<string | null>(null);
  const [removing, setRemoving] = useState(false);

  const firstLoad = useRef(true);

  /**
   * Las dos listas, en paralelo y en el mismo efecto: una carga, un error. Si
   * alguna de las dos rechaza, no se pinta ninguna tabla.
   *
   * Los hooks se declaran siempre; el efecto sale sin hacer nada si el miembro de
   * sesión no es ADMIN, de modo que un Editor no dispara ni una petición.
   */
  useEffect(() => {
    if (!isAdmin) return;

    let cancelled = false;

    if (firstLoad.current) {
      firstLoad.current = false;
      setLoading(true);
    }
    setLoadError(null);

    Promise.all([fetchTeam(profile.orgId), fetchInvitations()])
      .then(([members, rows]) => {
        if (cancelled) return;
        setTeam(members);
        setInvitations(rows);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setTeam([]);
        setInvitations([]);
        setLoadError(message(err));
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [isAdmin, profile.orgId, reloadToken]);

  /**
   * «Este email ya tiene cuenta», en tiempo real y sin debounce: cada vez que el
   * texto cambia y es un email con forma válida. La respuesta se guarda con el
   * texto al que corresponde, y el `cancelled` del efecto descarta la de un texto
   * que ya no es el actual.
   */
  useEffect(() => {
    if (!isValidEmail(email)) {
      setCheck(null);
      setChecking(false);
      return;
    }

    let cancelled = false;
    setChecking(true);

    emailHasAccount(email)
      .then((hasAccount) => {
        if (cancelled) return;
        setCheck({ email, hasAccount });
      })
      .catch(() => {
        if (cancelled) return;
        // «No se sabe»: no se bloquea el envío. El servidor lo comprobará.
        setCheck({ email, hasAccount: false });
      })
      .finally(() => {
        if (!cancelled) setChecking(false);
      });

    return () => {
      cancelled = true;
    };
  }, [email]);

  /** Cualquier cambio del texto borra el mensaje anterior. */
  function handleEmailChange(event: ChangeEvent<HTMLInputElement>) {
    setEmail(event.target.value);
    setFeedback(null);
  }

  /**
   * Un solo `inviteMember`. Si sale bien se vacía el campo, se avisa de que la
   * invitación queda registrada y se recargan las dos listas; si rechaza, el campo
   * NO se vacía y el servidor manda el motivo.
   */
  async function handleSend() {
    setFeedback(null);
    setSending(true);

    try {
      await inviteMember(email);
      setEmail('');
      setCheck(null);
      setFeedback({ tone: 'ok', text: INVITE_OK });
      setReloadToken((n) => n + 1);
    } catch (err: unknown) {
      setFeedback({ tone: 'error', text: message(err) });
    } finally {
      setSending(false);
    }
  }

  /** `Reenviar` de una invitación expirada: el límite lo vuelve a comprobar el servidor. */
  async function handleResend(id: string) {
    setResending(true);

    try {
      await resendInvitation(id);
      setFeedback({ tone: 'ok', text: RESEND_OK });
      setReloadToken((n) => n + 1);
    } catch (err: unknown) {
      setFeedback({ tone: 'error', text: message(err) });
    } finally {
      setResending(false);
    }
  }

  /** Abrir el diálogo borra el error anterior. */
  function handleRemove(member: TeamMember) {
    setPendingRemove(member);
    setRemoveError(null);
  }

  function handleCancelRemove() {
    setPendingRemove(null);
    setRemoveError(null);
  }

  /**
   * «Eliminar» es revocar (`members.state = 'CANCELLED'`): el usuario pierde el
   * acceso en el acto y deja de ocupar plaza. Si el servidor rechaza, el diálogo
   * sigue abierto con el motivo dentro.
   */
  async function handleConfirmRemove() {
    if (pendingRemove === null) return;
    setRemoving(true);

    try {
      await removeMember(pendingRemove.id);
      setPendingRemove(null);
      setRemoveError(null);
      setReloadToken((n) => n + 1);
    } catch (err: unknown) {
      setRemoveError(message(err));
    } finally {
      setRemoving(false);
    }
  }

  if (!isAdmin) {
    return <p className={styles.status}>Esta pantalla es solo para administradores.</p>;
  }

  if (loading) {
    return (
      <p role="status" className={styles.status}>
        Cargando invitaciones…
      </p>
    );
  }

  if (loadError !== null) {
    return (
      <p role="alert" className={styles.alert}>
        {loadError}
      </p>
    );
  }

  const limit = limitReached(team, invitations);
  const hasAccount = check !== null && check.email === email && check.hasAccount;
  const dots = capacityDots(team, invitations);
  const busy = resending || removing;
  const canSend = isValidEmail(email) && !limit && !sending && !checking && !hasAccount;

  return (
    <div className={styles.screen}>
      <div className={styles.content}>
        <p className={styles.eyebrow}>Módulo 01 · Onboarding</p>
        <h1 className={styles.title}>Gestión de invitaciones</h1>
        <p className={styles.subtitle}>
          Invita a los usuarios de tu organización. Cada nuevo usuario se incorporará con rol{' '}
          <strong>Editor</strong>. Límite: 5 usuarios por organización.
        </p>

        <div className={styles.capacityRow}>
          <div className={styles.dots} data-testid="capacity-dots">
            {dots.map((dot, index) => (
              <span
                key={index}
                className={`${styles.dot} ${DOT_CLASSES[dot]}`}
                title={DOT_TITLES[dot]}
              />
            ))}
          </div>
          <span className={styles.count} data-testid="capacity-count">
            {capacityLabel(team)}
          </span>
          <span className={styles.detail} data-testid="capacity-detail">
            {capacityDetail(team, invitations)}
          </span>
        </div>

        {limit && (
          <p className={styles.notice} role="note">
            <svg
              className={styles.noticeIcon}
              width="16"
              height="16"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth={1.8}
              strokeLinecap="round"
              strokeLinejoin="round"
              aria-hidden="true"
            >
              <circle cx="12" cy="12" r="10" />
              <line x1="12" y1="8" x2="12" y2="12" />
              <line x1="12" y1="16" x2="12.01" y2="16" />
            </svg>
            {LIMIT_NOTICE}
          </p>
        )}

        <div className={styles.card}>
          <h2 className={styles.cardTitle}>Invitar nuevo usuario</h2>
          <div className={styles.inviteRow}>
            <input
              className={styles.input}
              type="email"
              aria-label="Email del nuevo usuario"
              placeholder="email@empresa.com"
              autoComplete="email"
              value={email}
              onChange={handleEmailChange}
              disabled={limit || sending}
            />
            <button type="button" className={styles.button} onClick={handleSend} disabled={!canSend}>
              Enviar invitación
            </button>
          </div>

          {hasAccount && (
            <p className={styles.fieldError} role="alert">
              {EMAIL_TAKEN}
            </p>
          )}

          {feedback !== null && (
            <p
              className={feedback.tone === 'ok' ? styles.feedbackOk : styles.feedbackError}
              role={feedback.tone === 'ok' ? 'status' : 'alert'}
            >
              {feedback.text}
            </p>
          )}
        </div>

        <InvitationTables
          invitations={invitations}
          team={team}
          selfId={profile.id}
          busy={busy}
          onResend={handleResend}
          onRemove={handleRemove}
        />

        {pendingRemove !== null && (
          <RemoveMemberDialog
            member={pendingRemove}
            busy={removing}
            error={removeError}
            onConfirm={handleConfirmRemove}
            onCancel={handleCancelRemove}
          />
        )}
      </div>
    </div>
  );
}

