/* Confirmación de eliminación de INVT-01. Solo tokens de `tokens.css`. */

.overlay {
  position: fixed;
  inset: 0;
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  /* El único oscuro translúcido del sistema; §6.1 prohíbe escribir el rgba a mano. */
  background: var(--bw-sidebar-overlay);
}

.dialog {
  width: 100%;
  max-width: 420px;
  background: var(--bw-warm-cream);
  border-radius: 6px;
  padding: 28px;
  /* Sin token de sombra: se reutiliza el oscuro translúcido del overlay. */
  box-shadow: 0 20px 60px var(--bw-sidebar-overlay);
}

.title {
  font-family: var(--bw-font-title);
  font-weight: 700;
  font-size: var(--bw-size-body);
  color: var(--bw-deep-steel);
  letter-spacing: var(--bw-ls-title);
  margin-bottom: 10px;
}

.person {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin-bottom: 16px;
}

.name {
  font-weight: 600;
  font-size: var(--bw-size-body);
  color: var(--bw-ink-steel);
}

.email {
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-label);
  color: var(--bw-steel-mist);
}

.warning {
  background: var(--bw-sensitive-bg);
  border-left: 3px solid var(--bw-danger);
  border-radius: 0 var(--bw-radius) var(--bw-radius) 0;
  padding: 10px 12px;
  margin-bottom: 20px;
  font-size: var(--bw-size-label);
  color: var(--bw-sensitive-text);
  line-height: 1.5;
}

.error {
  margin-bottom: 16px;
  font-size: var(--bw-size-label);
  color: var(--bw-error-text);
}

.actions {
  display: flex;
  gap: 10px;
}

.cancel {
  flex: 1;
  padding: 10px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  background: var(--bw-warm-cream);
  color: var(--bw-ink-steel);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-body);
  font-weight: 500;
  cursor: pointer;
  transition: background 0.15s;
}

.cancel:hover:not(:disabled) {
  background: var(--bw-hover-surface);
}

.confirm {
  flex: 1;
  padding: 10px;
  border: none;
  border-radius: var(--bw-radius);
  background: var(--bw-danger);
  /* Texto sobre el rojo: el casi-blanco del sistema. */
  color: var(--bw-warm-cream);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-body);
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s;
}

.confirm:hover:not(:disabled) {
  background: var(--bw-error-text);
}

.cancel:disabled,
.confirm:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

import { useEffect, useRef } from 'react';
import type { TeamMember } from '../../lib/invitations';
import styles from './RemoveMemberDialog.module.css';

interface Props {
  member: TeamMember;
  busy: boolean;
  error: string | null;
  onConfirm: () => void;
  onCancel: () => void;
}

const TITLE_ID = 'remove-member-title';

/**
 * Confirmación de la eliminación de un miembro (INVT-01).
 *
 * Presentacional: no elimina nada por su cuenta, avisa a la pantalla con
 * `onConfirm`. Nunca se usa `window.confirm`: el diálogo es HTML normal, con
 * `role="dialog"`, Escape para cancelar y el foco en `Cancelar` al abrirse, para
 * que la acción irreversible no esté a un Enter de distancia.
 */
export function RemoveMemberDialog({ member, busy, error, onConfirm, onCancel }: Props) {
  const cancelRef = useRef<HTMLButtonElement | null>(null);

  /** Escape cancela; el listener vive en `document` y se retira al desmontar. */
  useEffect(() => {
    function handleKeyDown(event: KeyboardEvent) {
      if (event.key === 'Escape') onCancel();
    }

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [onCancel]);

  /** Al abrirse, el foco va al botón secundario. */
  useEffect(() => {
    cancelRef.current?.focus();
  }, []);

  return (
    <div className={styles.overlay}>
      <div role="dialog" aria-modal="true" aria-labelledby={TITLE_ID} className={styles.dialog}>
        <h2 id={TITLE_ID} className={styles.title}>
          Eliminar usuario
        </h2>

        <div className={styles.person}>
          <span className={styles.name}>{member.fullName}</span>
          <span className={styles.email}>{member.email}</span>
        </div>

        <p className={styles.warning}>
          Esta acción es irreversible. El usuario perderá acceso inmediatamente.
        </p>

        {error !== null && (
          <p className={styles.error} role="alert">
            {error}
          </p>
        )}

        <div className={styles.actions}>
          <button
            ref={cancelRef}
            type="button"
            className={styles.cancel}
            onClick={onCancel}
            disabled={busy}
          >
            Cancelar
          </button>
          <button type="button" className={styles.confirm} onClick={onConfirm} disabled={busy}>
            Eliminar
          </button>
        </div>
      </div>
    </div>
  );
}
